# Bank zadań autorskich — partia 6: wiek XIX, średniowiecze, nowożytność (ciąg dalszy).
# B(tytuł, materiał, *zadania) — wiązka; T(typ, punkty, polecenie, odpowiedź, omówienie) — zadanie.
BANK = {}

BANK['xix-wiek'] = [
 B('Niepodległość Ameryki Łacińskiej',
   'Tekst (autorski). Po tym jak Napoleon zajął Hiszpanię (1808), kolonie w Ameryce przestały uznawać władzę Madrytu. W kolejnych latach Kreole — potomkowie Hiszpanów urodzeni w Ameryce — poprowadzili wojny o niepodległość. Jeden z ich wodzów marzył o federacji wszystkich wyzwolonych państw.',
   T('abcd', 1, 'Dokończ zdanie. Wodzem, o którym mowa w ostatnim zdaniu, był\nA. Simón Bolívar.\nB. José de San Martín.\nC. Bernardo O’Higgins.\nD. Toussaint Louverture.',
     'A',
     'Bolívar („Libertador”) wyzwolił m.in. Wenezuelę, Kolumbię i Boliwię i chciał je zjednoczyć. San Martín wyzwalał Argentynę, Chile i Peru, O’Higgins — Chile, a Toussaint Louverture stał na czele powstania na Haiti (koniec XVIII w.).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy wydarzenia w Europie miały wpływ na początek walk o niepodległość opisanych w tekście. Uzasadnij.',
     'Tak — zajęcie Hiszpanii przez Napoleona i obalenie króla osłabiło władzę metropolii nad koloniami, co Kreole wykorzystali, by przejąć władzę.',
     'Zadanie sprawdza synchronizację: wojny napoleońskie w Europie → rozpad imperium hiszpańskiego w Ameryce.')),

 B('Francja Napoleona III',
   'Tekst (autorski). Bratanek wielkiego cesarza wygrał wybory prezydenckie w 1848 r., a trzy lata później przeprowadził zamach stanu. W 1852 r., po plebiscycie, ogłosił się cesarzem. Jego panowanie skończyło się klęską w wojnie z Prusami.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy droga do władzy opisana w tekście przypomina drogę Napoleona Bonaparte. Uzasadnij.',
     'Tak — obaj zdobyli władzę w republice, przeprowadzili zamach stanu, a następnie ogłosili się cesarzami po zatwierdzeniu w plebiscycie.',
     'Napoleon I: zamach 18 brumaire’a (1799) → konsulat → cesarstwo (1804). Napoleon III: prezydent (1848) → zamach (1851) → cesarstwo (1852).'),
   T('abcd', 1, 'Dokończ zdanie. Panowanie Napoleona III zakończyła klęska pod\nA. Sadową.\nB. Sedanem.\nC. Waterloo.\nD. Lipskiem.',
     'B',
     'Sedan (1870). Sadowa (1866) to klęska Austrii z Prusami, Waterloo (1815) i Lipsk (1813) to klęski Napoleona I.')),

 B('Reformy wyborcze w Wielkiej Brytanii',
   'Tekst (autorski, w duchu petycji ruchu robotniczego z 1838 r.). Domagamy się prawa wyborczego dla wszystkich mężczyzn, tajnego głosowania, corocznych wyborów do parlamentu, wynagrodzenia dla posłów i zniesienia wymogu majątkowego dla kandydatów.',
   T('podaj', 1, 'Podaj nazwę ruchu, który sformułował postulaty z tekstu.', 'Czartyzm (czartyści).',
     'Nazwa pochodzi od „Karty Ludu” (People’s Charter, 1838).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy postulaty z tekstu zostały spełnione przez reformę wyborczą z 1832 r. Uzasadnij.',
     'Nie — tekst pochodzi z 1838 r., czyli po reformie z 1832 r., która rozszerzyła prawo wyborcze głównie na średnią burżuazję; robotnicy nadal nie mogli głosować, dlatego powstał ruch czartystów.',
     'W tym zadaniu kluczem jest data tekstu — postulaty pojawiły się właśnie dlatego, że reforma z 1832 r. ich nie spełniła.')),

 B('Sztuka i literatura w służbie narodu',
   'Tekst (autorski). Malarz z Krakowa poświęcił życie wielkim obrazom przedstawiającym zwycięstwa i przełomowe chwile dziejów Polski. Pisarz z Warszawy w trylogii o XVII w. chciał „pokrzepić serca” rodaków żyjących pod zaborami.',
   T('podaj', 1, 'Podaj nazwiska malarza i pisarza opisanych w tekście.', 'Jan Matejko i Henryk Sienkiewicz.',
     'Trylogia: „Ogniem i mieczem”, „Potop”, „Pan Wołodyjowski”. Obrazy Matejki: „Bitwa pod Grunwaldem”, „Hołd pruski”, „Konstytucja 3 Maja”.'),
   T('abcd', 1, 'Dokończ zdanie. Obraz Jana Matejki przedstawiający wydarzenie z 1525 r. to\nA. „Bitwa pod Grunwaldem”.\nB. „Hołd pruski”.\nC. „Stańczyk”.\nD. „Rejtan — upadek Polski”.',
     'B',
     'Hołd pruski (1525). „Stańczyk” dotyczy utraty Smoleńska (1514), „Rejtan” — sejmu rozbiorowego (1773), „Bitwa pod Grunwaldem” — 1410.')),

 B('Uwłaszczenie w trzech zaborach',
   'Zestawienie (autorskie). A — uwłaszczenie w zaborze pruskim, prowadzone stopniowo za odszkodowaniem dla właścicieli; B — uwłaszczenie w Galicji ogłoszone w czasie Wiosny Ludów; C — uwłaszczenie w Królestwie Polskim ogłoszone ukazem carskim.',
   T('uporzadkuj', 1, 'Uporządkuj uwłaszczenia A–C chronologicznie.',
     'A, B, C.',
     'Zabór pruski: od 1823 r. (na podstawie edyktów z 1811 i 1823 r.) → Galicja: 1848 r. → Królestwo Polskie: 1864 r.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy uwłaszczenie w Królestwie Polskim (1864) miało cel wyłącznie społeczny. Uzasadnij.',
     'Nie — miało też cel polityczny: car chciał pozyskać chłopów i osłabić szlachtę, która poparła powstanie styczniowe; dlatego warunki były korzystniejsze niż w innych zaborach.',
     'Ukaz z 2 marca 1864 r. to odpowiedź na dekrety uwłaszczeniowe Rządu Narodowego — rywalizacja o chłopa.')),

 B('Śląsk na przełomie XIX i XX w.',
   'Tekst (autorski). Polityk ze Śląska jako pierwszy kandydat polskiej listy wygrał w 1903 r. wybory do parlamentu Rzeszy w okręgu górnośląskim. Wcześniej śląscy Polacy głosowali głównie na niemiecką partię katolicką. Po I wojnie światowej ten sam polityk stanął na czele powstania.',
   T('abcd', 1, 'Dokończ zdanie. Politykiem opisanym w tekście był\nA. Wojciech Korfanty.\nB. Józef Piłsudski.\nC. Roman Dmowski.\nD. Ignacy Daszyński.',
     'A',
     'Korfanty — poseł do Reichstagu od 1903 r., przywódca III powstania śląskiego (1921). Daszyński był posłem do parlamentu austriackiego z Galicji, Dmowski — posłem do rosyjskiej Dumy.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Górny Śląsk przed I wojną światową należał do Prus.\n2. Niemiecką partią katolicką, o której mowa w tekście, było Centrum.\n3. Korfanty był posłem do rosyjskiej Dumy.',
     '1 – P, 2 – P, 3 – F.',
     'Korfanty zasiadał w Reichstagu i w pruskim Landtagu. W Dumie zasiadali posłowie z Królestwa Polskiego (m.in. Dmowski).')),
]

BANK['sredniowiecze'] = [
 B('Unia w Horodle',
   'Tekst (autorski, na podstawie aktu z 1413 r.). Bojarzy litewscy, którzy przyjęli wiarę katolicką, otrzymują takie same przywileje jak szlachta polska. Czterdzieści siedem rodów polskich przyjmuje rody litewskie do swoich herbów. Litwa zachowuje odrębnego wielkiego księcia, a ważne sprawy obu państw mają być omawiane na wspólnych zjazdach.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy unia opisana w tekście zlikwidowała odrębność Litwy. Uzasadnij.',
     'Nie — Litwa zachowała własnego wielkiego księcia; unia zbliżyła elity obu państw (przywileje, adopcja herbowa) i przewidywała wspólne zjazdy, ale nie łączyła państw w jedno.',
     'Etapy unii: Krewo (1385) → Wilno-Radom (1401) → Horodło (1413) → Lublin (1569, wspólny sejm i król — Rzeczpospolita Obojga Narodów).'),
   T('podaj', 1, 'Podaj, które bojarstwo litewskie zostało objęte przywilejami z tekstu, a które nie.',
     'Objęte: bojarzy katolicy. Nieobjęci: bojarzy prawosławni (ruscy).',
     'Ograniczenie do katolików wywołało niezadowolenie prawosławnych — co Świdrygiełło wykorzysta w walce o władzę na Litwie.')),

 B('Witold i Litwa',
   'Tekst (autorski). Kuzyn króla polskiego przez blisko czterdzieści lat rządził Litwą jako wielki książę. Walczył razem z Polakami pod Grunwaldem, rozszerzył granice aż do Morza Czarnego, a pod koniec życia starał się o koronę królewską dla siebie.',
   T('abcd', 1, 'Dokończ zdanie. Tekst opisuje\nA. Witolda.\nB. Świdrygiełłę.\nC. Zygmunta Kiejstutowicza.\nD. Olgierda.',
     'A',
     'Witold (wielki książę 1392–1430). Olgierd był ojcem Jagiełły (XIV w.), Świdrygiełło — bratem Jagiełły, a Zygmunt Kiejstutowicz — bratem Witolda; obaj walczyli o władzę po jego śmierci.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy starania Witolda o koronę były zgodne z interesami polskich możnych. Uzasadnij.',
     'Nie — korona dla Witolda oznaczałaby oddzielenie Litwy od Polski i osłabienie unii; polscy możni (m.in. Zbigniew Oleśnicki) blokowali przesłanie korony.',
     'Koronę przesyłaną od cesarza Zygmunta Luksemburskiego zatrzymali Polacy na granicy (1430). Witold zmarł niekoronowany.')),

 B('I pokój toruński',
   'Tekst (autorski). Po zwycięstwie pod Grunwaldem wojska polsko-litewskie nie zdobyły Malborka. W 1411 r. zawarto pokój, na mocy którego Litwa odzyskała Żmudź (dożywotnio dla Jagiełły i Witolda), Polska — ziemię dobrzyńską, a zakon zapłacił wysokie odszkodowanie.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy postanowienia pokoju odpowiadały skali zwycięstwa grunwaldzkiego. Uzasadnij.',
     'Nie — mimo wielkiego zwycięstwa Polska nie odzyskała Pomorza Gdańskiego ani ziemi chełmińskiej, a Żmudź wróciła do Litwy tylko dożywotnio; zakon zachował swoje państwo.',
     'Przyczyny: nieudane oblężenie Malborka i brak środków na dalszą wojnę. Za to odszkodowanie wojenne mocno osłabiło finanse zakonu.'),
   T('abcd', 1, 'Dokończ zdanie. Wielkim mistrzem, który obronił Malbork po bitwie pod Grunwaldem, był\nA. Ulrich von Jungingen.\nB. Henryk von Plauen.\nC. Konrad von Wallenrod.\nD. Albrecht Hohenzollern.',
     'B',
     'Ulrich von Jungingen zginął pod Grunwaldem. Henryk von Plauen obronił Malbork i został wielkim mistrzem. Konrad von Wallenrod to wielki mistrz z XIV w. (i bohater powieści Mickiewicza), Albrecht — ostatni mistrz w Prusach (1525).')),

 B('Elżbieta Rakuszanka',
   'Tekst (autorski). Żona Kazimierza Jagiellończyka z rodu Habsburgów urodziła trzynaścioro dzieci. Czterech jej synów zostało królami, a jeden — kardynałem i świętym. Z tego powodu nazywano ją „matką królów”.',
   T('abcd', 1, 'Dokończ zdanie. Synem Elżbiety Rakuszanki NIE był\nA. Jan Olbracht.\nB. Aleksander Jagiellończyk.\nC. Władysław Warneńczyk.\nD. Zygmunt Stary.',
     'C',
     'Władysław Warneńczyk był bratem Kazimierza Jagiellończyka (synem Jagiełły), czyli stryjem synów Elżbiety. Jej synowie-królowie to Władysław (Czechy, Węgry), Jan Olbracht, Aleksander i Zygmunt Stary; św. Kazimierz był królewiczem.'),
   T('wyjasnij', 1, 'Wyjaśnij, jakie znaczenie dla pozycji Jagiellonów w Europie miało małżeństwo opisane w tekście.',
     'Elżbieta pochodziła z rodu Luksemburgów (po matce) i Habsburgów; dało to Jagiellonom prawa do tronów Czech i Węgier, które objął jej najstarszy syn Władysław.',
     'Pod koniec XV w. Jagiellonowie rządzili w Polsce, na Litwie, w Czechach i na Węgrzech — szczyt potęgi dynastii.')),

 B('Jan Długosz',
   'Tekst (autorski). Kanonik krakowski, wychowawca synów Kazimierza Jagiellończyka, przez blisko trzydzieści lat pisał dzieje Polski od czasów legendarnych do 1480 r. Korzystał z dokumentów, kronik i relacji świadków, a dzieło pisał po łacinie.',
   T('podaj', 1, 'Podaj tytuł dzieła opisanego w tekście (w wersji polskiej lub łacińskiej).',
     '„Roczniki, czyli kroniki sławnego Królestwa Polskiego” („Annales seu cronicae incliti Regni Poloniae”).',
     'Długosz był też autorem „Banderia Prutenorum” — opisu chorągwi krzyżackich zdobytych pod Grunwaldem.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy dzieło Długosza jest dla historyka źródłem w pełni bezstronnym. Uzasadnij.',
     'Nie — autor był związany z dworem i Kościołem, miał własne sympatie polityczne (np. był krytyczny wobec niektórych władców), a o wydarzeniach dawnych pisał na podstawie legend i starszych kronik.',
     'Typowe zadanie z krytyki źródeł: zawsze sprawdź, kim był autor, kiedy pisał i dla kogo.')),
]

BANK['nowozytnosc'] = [
 B('Pierwsza podróż dookoła świata',
   'Tekst (autorski). W 1519 r. z Hiszpanii wypłynęło pięć statków pod dowództwem portugalskiego żeglarza. Przepłynęły cieśninę na południu Ameryki i ocean, który żeglarz nazwał Spokojnym. Sam dowódca zginął na Filipinach, a do Hiszpanii w 1522 r. wrócił tylko jeden statek.',
   T('abcd', 1, 'Dokończ zdanie. Dowódcą wyprawy opisanej w tekście był\nA. Vasco da Gama.\nB. Ferdynand Magellan.\nC. Bartolomeu Dias.\nD. Amerigo Vespucci.',
     'B',
     'Magellan (wyprawę dokończył Juan Sebastián Elcano). Dias opłynął Przylądek Dobrej Nadziei (1488), Vasco da Gama dotarł do Indii (1498), Vespucci uznał, że Kolumb odkrył nowy kontynent.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy wyprawa opisana w tekście dostarczyła dowodu na kulistość Ziemi. Uzasadnij.',
     'Tak — statek płynący stale na zachód wrócił do punktu wyjścia, co praktycznie potwierdziło, że Ziemia jest kulą.',
     'Ludzie wykształceni wiedzieli o kulistości Ziemi już w starożytności — wyprawa Magellana dostarczyła dowodu doświadczalnego i pokazała rozmiar oceanów.')),

 B('Jezuici',
   'Tekst (autorski). Zakon założony w 1540 r. przez byłego żołnierza z Hiszpanii stawiał na posłuszeństwo papieżowi, zakładanie szkół i działalność misyjną. W Rzeczypospolitej jego kolegia kształciły synów szlachty, a jeden z członków zakonu wygłaszał słynne kazania przed sejmem.',
   T('abcd', 1, 'Dokończ zdanie. Założycielem zakonu opisanego w tekście był\nA. Ignacy Loyola.\nB. Franciszek Ksawery.\nC. Dominik Guzmán.\nD. Piotr Kanizjusz.',
     'A',
     'Ignacy Loyola. Franciszek Ksawery był jezuickim misjonarzem w Azji, Piotr Kanizjusz — jezuitą działającym w Niemczech, a św. Dominik założył zakon dominikanów w XIII w.'),
   T('podaj', 1, 'Podaj nazwisko jezuity, autora „Kazań sejmowych”.', 'Piotr Skarga.',
     'Skarga krytykował słabość władzy królewskiej i prywatę szlachty — w XIX w. uznano go za „proroka” upadku Rzeczypospolitej (obraz Matejki „Kazanie Skargi”).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy działalność zakonu opisanego w tekście była częścią reformacji. Uzasadnij.',
     'Nie — była częścią kontrreformacji (reformy katolickiej): zakon bronił papiestwa i przeciwdziałał rozwojowi protestantyzmu, m.in. przez szkoły.',
     'Narzędzia kontrreformacji: sobór trydencki, jezuici, inkwizycja, indeks ksiąg zakazanych.')),

 B('Inflanty w XVI w.',
   'Tekst (autorski). W 1561 r. ostatni mistrz zakonu kawalerów mieczowych oddał swoje państwo pod zwierzchnictwo króla polskiego i przyjął w lenno Kurlandię. Inflanty stały się terenem długotrwałej rywalizacji między Rzecząpospolitą, Moskwą i Szwecją.',
   T('abcd', 1, 'Dokończ zdanie. Wydarzenie opisane w tekście nastąpiło za panowania\nA. Zygmunta Starego.\nB. Zygmunta Augusta.\nC. Stefana Batorego.\nD. Zygmunta III Wazy.',
     'B',
     'Zygmunt August przyjął Inflanty pod zwierzchnictwo (1561); mistrz Gotthard Kettler został księciem Kurlandii. Batory później wywalczył Inflanty w wojnie z Iwanem Groźnym (1577–1582).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy Rzeczpospolita utrzymała całe Inflanty do końca XVII w. Uzasadnij.',
     'Nie — po wojnach ze Szwecją większość Inflant (z Rygą) przeszła pod panowanie szwedzkie (rozejm w Altmarku 1629, pokój w Oliwie 1660); przy Rzeczypospolitej zostały tylko Inflanty Polskie (Łatgalia).',
     'Ryga została zajęta przez Szwedów w 1621 r. To dobry przykład skutków wojen polsko-szwedzkich na mapie.')),

 B('Plany wojny z Turcją Władysława IV',
   'Tekst (autorski). W latach czterdziestych XVII w. król potajemnie przygotowywał wielką wojnę z Turcją. Werbował wojsko i obiecywał Kozakom zwiększenie rejestru. Sejm w 1646 r. zmusił go do rozpuszczenia zaciągów, a rozczarowani Kozacy dwa lata później wystąpili przeciw Rzeczypospolitej.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy wydarzenia z tekstu można uznać za jedną z przyczyn powstania Chmielnickiego. Uzasadnij.',
     'Tak — Kozacy liczyli na wojnę i zwiększenie rejestru (czyli lepszą pozycję i żołd), a decyzja sejmu przekreśliła te nadzieje, co pogłębiło ich niezadowolenie przed 1648 r.',
     'Inne przyczyny powstania: konflikty religijne (unia brzeska), ucisk chłopów ukraińskich, spory o rejestr kozacki, osobista krzywda Chmielnickiego.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Rejestr kozacki był listą Kozaków na żołdzie Rzeczypospolitej.\n2. Sejm z 1646 r. poparł plany wojny tureckiej.\n3. Władysław IV zmarł w roku wybuchu powstania Chmielnickiego.',
     '1 – P, 2 – F, 3 – P.',
     'Władysław IV zmarł w maju 1648 r., na początku powstania. Sejm z 1646 r. sprzeciwił się wojnie.')),
]
